class Solution {
    public int largestSumAfterKNegations(int[] nums, int k) {
        while (k-- > 0) {
            int idx = 0;
            for (int i = 1; i < nums.length; i++)
                if (nums[i] < nums[idx]) idx = i;
            nums[idx] = -nums[idx];
        }
        int sum = 0;
        for (int x : nums) sum += x;
        return sum;
    }
}

