class Solution:
    def largestSumAfterKNegations(self, nums: List[int], k: int) -> int:
        nums.sort()
        for i in range(len(nums)):
            if nums[i] < 0 and k > 0:
                nums[i] = -nums[i]
                k -= 1
        s = sum(nums)
        if k % 2 == 1:
            s -= 2 * min(abs(x) for x in nums)
        return s

