class Solution {
public:
    int largestSumAfterKNegations(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        for (int& x : nums) {
            if (x < 0 && k > 0) { x = -x; k--; }
        }
        int sum = 0, mn = INT_MAX;
        for (int x : nums) { sum += x; mn = min(mn, abs(x)); }
        if (k % 2 == 1) sum -= 2 * mn;
        return sum;
    }
};

