        Arrays.sort(nums);
        for (int i = 0; i < nums.length && k > 0; i++) {
            if (nums[i] < 0) { nums[i] = -nums[i]; k--; }
        }
        int sum = 0, mn = Integer.MAX_VALUE;
        for (int x : nums) { sum += x; mn = Math.min(mn, Math.abs(x)); }
        if (k % 2 == 1) sum -= 2 * mn;
        return sum;
    }
}

